<script setup lang="ts">
import { useI18n } from 'vue-i18n'

withDefaults(
  defineProps<{
    title: string
    createText?: string
    canCreate?: boolean
  }>(),
  {
    createText: undefined,
    canCreate: true,
  },
)

const { t } = useI18n()

const emit = defineEmits<{
  create: []
}>()
</script>

<template>
  <div class="crud-toolbar">
    <h2 class="title">{{ title }}</h2>
    <el-button v-if="canCreate" type="primary" @click="emit('create')">
      {{ createText || t('common.new') }}
    </el-button>
  </div>
</template>

